CustomField.formula:
IF( ISPICKVAL( Benefit__r.Benefit_Type__c , "Death Benefit"), Start_Date__c + Smart_Goal_in_Days__c, IF( ISPICKVAL( Benefit__r.Benefit_Type__c , "Retirement"), /* Get the last calendar day of this month */ IF( /* If last day is Saturday */ CASE( WEEKDAY( DATE( YEAR(TODAY()), MONTH(TODAY()) + 1, 1 ) - 1 ), 1, "Sun", 2, "Mon", 3, "Tue", 4, "Wed", 5, "Thu", 6, "Fri", 7, "Sat", "" ) = "Sat", /* Then last business day is that date minus 1 day (Friday) */ (DATE( YEAR(TODAY()), MONTH(TODAY()) + 1, 1 ) - 1) - 1,
/* else if last day is Sunday */ IF( CASE( WEEKDAY( DATE( YEAR(TODAY()), MONTH(TODAY()) + 1, 1 ) - 1 ), 1, "Sun", 2, "Mon", 3, "Tue", 4, "Wed", 5, "Thu", 6, "Fri", 7, "Sat", "" ) = "Sun", /* Then last business day is that date minus 2 days (Friday) */ (DATE( YEAR(TODAY()), MONTH(TODAY()) + 1, 1 ) - 1) - 2,
/* else it's already a weekday, just use it */ DATE( YEAR(TODAY()), MONTH(TODAY()) + 1, 1 ) - 1 ) ), NULL))
